 OR NOT(OLD.raw_body IS NOT NULL AND OLD.consumed_at IS NULL AND NEW.raw_body IS NULL AND NEW.raw_bytes=0 AND NEW.consumed_at IS NOT NULL AND (EXISTS(SELECT 1 FROM kids_hosted_history_heads h WHERE h.binding_id=OLD.binding_id AND h.chat_id=OLD.chat_id AND h.message_id=OLD.message_id AND h.message_sequence=OLD.sequence AND h.body_hash=OLD.body_hash AND h.fingerprint=OLD.fingerprint) OR EXISTS(SELECT 1 FROM kids_hosted_message_heads h JOIN kids_hosted_bindings b ON b.id=h.binding_id JOIN kids_source_records r ON r.owner_user_id=b.owner_user_id AND r.workspace_id=b.workspace_id AND (EXISTS(SELECT 1 FROM kids_chat_sources identity_chat WHERE identity_chat.owner_user_id=r.owner_user_id AND identity_chat.workspace_id=r.workspace_id AND identity_chat.binding_id=h.binding_id AND identity_chat.provider_chat_id=h.chat_id AND identity_chat.app_chat_id=r.chat_id)
 OR (r.chat_id=h.chat_id AND NOT EXISTS(SELECT 1 FROM kids_source_connections identity_connection WHERE identity_connection.owner_user_id=r.owner_user_id AND identity_connection.workspace_id=r.workspace_id))) AND r.message_id=h.message_id AND r.fingerprint=h.fingerprint JOIN kids_hosted_history_pages p ON p.id=OLD.page_id AND p.owner_user_id=b.owner_user_id AND p.workspace_id=b.workspace_id AND p.status='committed' AND p.response_hash IS NOT NULL WHERE h.binding_id=OLD.binding_id AND h.chat_id=OLD.chat_id AND h.message_id=OLD.message_id AND NOT EXISTS(SELECT 1 FROM kids_hosted_history_batch_members m JOIN kids_hosted_batches lease ON lease.id=m.batch_id WHERE m.message_sequence=OLD.sequence AND lease.source_kind='history' AND lease.status='ready')) OR EXISTS(SELECT 1 FROM kids_hosted_bindings b JOIN kids_hosted_removals r ON r.owner_user_id=b.owner_user_id AND r.workspace_id=b.workspace_id,json_each(r.bindings_json) x WHERE b.id=OLD.binding_id AND b.active=0 AND b.removed_at IS NOT NULL AND r.status='completed' AND json_extract(x.value,'$.id')=b.id)))
